"""Generate offline Kotlin catalog from the shared Android/Windows source."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[1]
moves = json.loads((root / "shared/exercises.json").read_text())
assert len({m["id"] for m in moves}) == len(moves)
q = lambda value: json.dumps(value, ensure_ascii=False)
entries = ",\n".join("        Move(" + ", ".join(q(m[k]) for k in ("id", "title", "steps", "source")) + ")" for m in moves)
code = '''package io.github.hugfeature.hydrationbreak

// Generated by scripts/generate-exercises.py; edit shared/exercises.json.
object OfficeExercises {
    data class Move(val id: String, val title: String, val steps: String, val source: String)
    const val EXTRA_MOVE = "office_move"
    const val CAUTION = "使用稳固、无轮子的椅子，动作轻缓、自然呼吸、不追求幅度。疼痛、头晕或不适就停止。有伤病或不确定是否适合时，请先咨询专业人员。这不是个体化康复方案。"
    val moves = listOf(
''' + entries + '''
    )
    fun at(index: Int) = moves[Math.floorMod(index, moves.size)]
    fun selected(context: android.content.Context): List<Int> {
        val ids = Scheduler.prefs(context).getStringSet("exercise_ids", null)
        return moves.indices.filter { ids == null || moves[it].id in ids }
    }
    fun nextSelected(context: android.content.Context, cursor: Int): Int? {
        val selected = selected(context).toSet()
        return (0 until moves.size).map { Math.floorMod(cursor + it, moves.size) }.firstOrNull { it in selected }
    }
}
'''
(root / "app/src/main/java/io/github/hugfeature/hydrationbreak/OfficeExercises.kt").write_text(code)
